import random
import sys
sys.path.insert(0, '.')
from matmul import matmul, _blocked_python_multiply, _strassen_multiply, _naive_multiply
try:
 import numpy as np
 HAS_NP=True
except ImportError:
 HAS_NP=False
def ref(a,b):
 m=len(a); k=len(a[0]); n=len(b[0])
 return [[sum(a[i][p]*b[p][j] for p in range(k)) for j in range(n)] for i in range(m)]
def rand_mat(m,k, zero_prob=0.0):
 M=[]
 for i in range(m):
  row=[]
  for j in range(k):
   if random.random()<zero_prob:
    row.append(0.0)
   else:
    row.append(random.uniform(-5,5))
  M.append(row)
 return M
def assert_close(C,E,tol=1e-6):
 assert len(C)==len(E), f"{len(C)} vs {len(E)}"
 for i in range(len(E)):
  assert len(C[i])==len(E[i])
  for j in range(len(E[i])):
   assert abs(C[i][j]-E[i][j])<=tol, f"mismatch [{i}][{j}]: {C[i][j]} vs {E[i][j]}"
def test_small():
 assert matmul([[1,2],[3,4]], [[5,6],[7,8]])==[[19.0,22.0],[43.0,50.0]]
def test_random_small():
 for _ in range(5):
  m,k,n=random.randint(1,5),random.randint(1,5),random.randint(1,5)
  a=rand_mat(m,k); b=rand_mat(k,n)
  assert_close(matmul(a,b), ref(a,b))
def test_zero_skip():
 a=[[0,2,0],[0,0,3]]; b=[[1,2],[3,4],[5,6]]
 assert_close(matmul(a,b), ref(a,b))
def test_blocked_python():
 a=rand_mat(10,8,zero_prob=0.3); b=rand_mat(8,9,zero_prob=0.3)
 assert_close(_blocked_python_multiply(a,b), ref(a,b))
 assert_close(matmul(a,b), ref(a,b))
def test_strassen_square():
 n=64
 a=rand_mat(n,n); b=rand_mat(n,n)
 assert_close(_strassen_multiply(a,b), ref(a,b), tol=1e-5)
 assert_close(matmul(a,b), ref(a,b), tol=1e-5)
def test_nonsquare_large_numpy():
 if not HAS_NP:
  return
 a=rand_mat(100,50); b=rand_mat(50,80)
 expected=(np.asarray(a)@np.asarray(b)).tolist()
 assert_close(matmul(a,b), expected, tol=1e-8)
def test_padding_nonsquare_strassen():
 a=rand_mat(33,17); b=rand_mat(17,40)
 assert_close(_strassen_multiply(a,b), ref(a,b), tol=1e-6)
def test_dim_mismatch():
 try:
  matmul([[1,2]], [[1]])
  assert False, "should raise"
 except ValueError:
  pass
def test_empty():
 assert matmul([], [])==[]
 assert matmul([[]], [[]])==[]

import pathlib
import importlib.util
import random
def _load_matmul():
    for p in pathlib.Path('.').rglob('*.py'):
        if p.name.startswith('test_'):
            continue
        try:
            t = p.read_text()
        except Exception:
            continue
        if 'def matmul' in t:
            spec = importlib.util.spec_from_file_location('cand_' + p.stem, p)
            mod = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(mod)
            return mod.matmul
    raise ImportError('matmul not found')
matmul = _load_matmul()
def _naive(a, b):
    m = len(a)
    k = len(a[0])
    n = len(b[0])
    C = [[0.0]*n for _ in range(m)]
    for i in range(m):
        for pp in range(k):
            for j in range(n):
                C[i][j] += a[i][pp]*b[pp][j]
    return C
def test_basic_2x2():
    assert matmul([[1,2],[3,4]], [[5,6],[7,8]]) == [[19.0,22.0],[43.0,50.0]]
def test_zero_skip_correctness():
    a = [[0,2],[0,0]]
    b = [[1,2],[3,4]]
    assert matmul(a,b) == [[6.0,8.0],[0.0,0.0]]
def test_non_square_padding():
    random.seed(1)
    a = [[random.uniform(-5,5) for _ in range(5)] for _ in range(3)]
    b = [[random.uniform(-5,5) for _ in range(2)] for _ in range(5)]
    exp = _naive(a,b)
    got = matmul(a,b)
    for i in range(3):
        for j in range(2):
            assert abs(got[i][j]-exp[i][j]) < 1e-9
def test_large_square_strassen_blocked():
    random.seed(0)
    n = 70
    a = [[random.uniform(-5,5) for _ in range(n)] for _ in range(n)]
    b = [[random.uniform(-5,5) for _ in range(n)] for _ in range(n)]
    exp = _naive(a,b)
    got = matmul(a,b)
    assert len(got)==n and len(got[0])==n
    for i in range(n):
        for j in range(n):
            assert abs(got[i][j]-exp[i][j]) < 1e-6, (i,j,got[i][j],exp[i][j])
def test_rect_large_blocked():
    random.seed(2)
    m,k,n = 30,45,20
    a = [[random.uniform(-3,3) for _ in range(k)] for _ in range(m)]
    b = [[random.uniform(-3,3) for _ in range(n)] for _ in range(k)]
    exp = _naive(a,b)
    got = matmul(a,b)
    for i in range(m):
        for j in range(n):
            assert abs(got[i][j]-exp[i][j]) < 1e-6
def test_dim_mismatch_raises():
    try:
        matmul([[1,2]], [[1]])
    except ValueError:
        return
    assert False, 'should raise ValueError'
